try_provider(_providers, _stats, _url) {
    _sorted = sort(_providers, 
        lambda(p) { 
            _key = concat("score_", p); 
            if3(dict_has(_stats, _key), 
                dict_get(_stats, _key), 
                0.5)
        }, false);

    loop(_sorted, lambda(provider) {
        _start = now();
        _result = try3 { 
            _resp = http_get(concat(provider, _url));
            { "ok": true, "data": _resp }
        } fail { 
            { "ok": false, "error": "failed" } 
        };

        _duration = subtract(now(), _start);
        _key_s = concat("success_", provider);
        _key_l = concat("latency_", provider);
        _key_c = concat("count_", provider);

        _success = if3(_result.ok, 1, 0);
        _count = if3(dict_has(_stats, _key_c), 
            dict_get(_stats, _key_c), 0);
        _latency = if3(dict_has(_stats, _key_l), 
            dict_get(_stats, _key_l), 0);

        _count_new = add(_count, 1);
        _latency_new = add(_latency, _duration);

        _stats = dict_set(_stats, _key_c, _count_new);
        _stats = dict_set(_stats, _key_l, _latency_new);
        _stats = dict_set(_stats, _key_s, 
            add(dict_get(_stats, _key_s, 0), _success));

        if3(_result.ok, 
            return(_result, _stats), 
            null);
    });

    return({ "ok": false, "error": "all_failed" }, _stats);
}

